using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
namespace FashionFit {
 public sealed class LayeredGarmentPlayerVerification:MonoBehaviour {
  [Serializable]sealed class Result{public string status="passed",scope="Windows player, real automatic updates/PhysX with injected near-hand inputs; no physical HMD";public int checks,exceptions;public bool wornHatPull,detachHat,gravity,poseShirt,mainShirt,layerSelection,twoLayers,tailLift,tailRecovery,pinHold,pinRelease,design;public float hatOffset,dropM,liftM,beforeRecovery,afterRecovery,pinDropM,meanFrameMs,p95FrameMs;public double maxLayerMs;}
  string output;FashionFitApp app;RunwayVRHands hands;Result result=new Result();List<float> times=new List<float>();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++)if(args[i]=="-fashionLayeredVerify"){var test=new GameObject("Layered garment explicit verification").AddComponent<LayeredGarmentPlayerVerification>();test.output=args[i+1];break;}}
  void Check(bool ok,string label){result.checks++;if(!ok)throw new InvalidOperationException(label);}void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)result.exceptions++;}
  IEnumerator Start(){Application.runInBackground=true;Directory.CreateDirectory(output+"/Contact");Application.logMessageReceived+=Log;var scenario=Scenario();while(true){object next=null;bool more=false;Exception fail=null;try{more=scenario.MoveNext();if(more)next=scenario.Current;}catch(Exception e){fail=e;}if(fail!=null){result.status="failed";File.WriteAllText(output+"/failure.txt",fail.ToString());Save();Application.Quit(1);yield break;}if(!more)break;yield return next;}Save();Application.Quit(0);}
  IEnumerator Scenario(){double deadline=Time.realtimeSinceStartupAsDouble+40;while(!app||!app.Ready){app=FindObjectOfType<FashionFitApp>();if(Time.realtimeSinceStartupAsDouble>deadline)throw new Exception("Startup timeout");yield return null;}app.Player.PrepareForVRTrial();app.Player.EnsureHands();hands=app.Player.Hands;if(app.Player.VRMenu)app.Player.VRMenu.Hide();app.PoseStudio.SetHandles(false);Check(Physics.simulationMode==SimulationMode.FixedUpdate,"No automatic PhysX");
   app.Showroom.SelectOutfitTarget(1);app.Showroom.WearHat(0);yield return new WaitForSecondsRealtime(.3f);var hat=app.Showroom.Hats[0];var v=hat.Elastic.MeshAt(0).vertices;int brim=0;for(int i=1;i<v.Length;i++)if(v[i].z>v[brim].z)brim=i;Vector3 p=hat.transform.TransformPoint(v[brim]);Grip(0,p,true);Check(hands.HeldBy(0),"Near hand cannot select worn hat");double end=Time.realtimeSinceStartupAsDouble+1;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.up*.10f,0);yield return null;}result.hatOffset=hat.Elastic.MaximumOffset;result.wornHatPull=hat.IsEquipped&&hat.Elastic.GrabCount==1&&result.hatOffset>.025f;Check(result.wornHatPull,"Worn hat is rigid or immediately removed");hands.ReleaseAll(false);hat.Elastic.ResetShape();yield return null;p=hat.transform.TransformPoint(hat.Elastic.MeshAt(0).vertices[brim]);Grip(0,p,false);result.detachHat=hat.IsHeld&&!hat.IsEquipped;Check(result.detachHat,"Normal Grip cannot remove hat");end=Time.realtimeSinceStartupAsDouble+.8;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.forward*.65f+Vector3.up*.08f,1);yield return null;}float y=hat.transform.position.y;hands.ReleaseAll(true);yield return new WaitForSecondsRealtime(.8f);result.dropM=y-hat.transform.position.y;result.gravity=hat.GetComponent<Rigidbody>().useGravity&&result.dropM>.1f;Check(result.gravity,"Removed hat has no gravity");hat.ReturnToDisplay();
   app.PoseStudio.Wear(0,5);yield return new WaitForSecondsRealtime(.4f);var surface=app.PoseStudio.Wearables[0].Surface;p=Chest(surface);Grip(0,p,false);Check(hands.HeldBy(0)&&hands.HeldBy(0).Elastic==surface,"Pose base still steals shirt touch");end=Time.realtimeSinceStartupAsDouble+.8;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.forward*.13f,0);yield return null;}result.poseShirt=surface.MaximumOffset>.025f&&surface.MaximumOffset<.065f;Check(result.poseShirt,"Pose shirt does not respond");hands.ReleaseAll(false);
   app.SetLook(5);yield return new WaitForSecondsRealtime(.4f);var main=app.Model.GetComponentInChildren<InteractiveShirt>();p=Chest(main.Surface);Grip(0,p,false);Check(hands.HeldBy(0)&&hands.HeldBy(0).Elastic==main.Surface,"Cannot grab main shirt");end=Time.realtimeSinceStartupAsDouble+.8;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.forward*.12f,0);yield return null;}result.mainShirt=main.Surface.MaximumOffset>.025f&&main.Surface.MaximumOffset<.065f;Check(result.mainShirt,"Main shirt is rigid");hands.ReleaseAll(false);app.SetLook(0);
   app.Showroom.SelectOutfitTarget(1);app.LayerLab.WearSelected();var ao=app.LayerLab.Current;yield return new WaitForSecondsRealtime(2.5f);Export(ao,"Player_Rest");ao.SelectLayer(1);int index=ao.Front.Positions.Length-7;Vector3[] baseline=(Vector3[])ao.Front.Positions.Clone();p=ao.Front.transform.TransformPoint(ao.Front.Positions[index]);float initialY=ao.Front.Positions[index].y;Grip(0,p,false);result.layerSelection=hands.HeldBy(0)&&hands.HeldBy(0).Panel==ao.Front&&!ao.Back.GetComponent<RunwayVRGrabTarget>().CanGrab;Check(result.layerSelection,"Selected layer cannot be pulled independently");end=Time.realtimeSinceStartupAsDouble+1.4;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.up*.30f+Vector3.forward*.13f,0);Record(ao);yield return null;}result.liftM=ao.Front.Positions[index].y-initialY;result.tailLift=result.liftM>.12f;Check(result.tailLift,"Tail does not lift in actual player updates");result.beforeRecovery=Error(ao.Front.Positions,baseline);Export(ao,"Player_Lift");hands.ReleaseAll(false);yield return new WaitForSecondsRealtime(5);result.afterRecovery=Error(ao.Front.Positions,baseline);result.tailRecovery=result.afterRecovery<result.beforeRecovery*.65f;Check(result.tailRecovery,"Tail does not recover");Export(ao,"Player_Recovery");
   ao.SelectLayer(-1);Vector3 a=ao.Front.transform.TransformPoint(ao.Front.Positions[index]),b=ao.Back.transform.TransformPoint(ao.Back.Positions[index]);Grip(0,a,false);Grip(1,b,false);result.twoLayers=hands.HeldCount==2&&hands.HeldBy(0).Panel==ao.Front&&hands.HeldBy(1).Panel==ao.Back;Check(result.twoLayers,"Two hands cannot hold separate tails");hands.Release(0,false);Check(hands.HeldCount==1&&ao.Back.GrabCount==1,"First release lost other tail");hands.Release(1,false);
   ao.SelectLayer(1);ao.ToggleArrangement();p=ao.Front.transform.TransformPoint(ao.Front.Positions[index]);Grip(0,p,false);end=Time.realtimeSinceStartupAsDouble+1;while(Time.realtimeSinceStartupAsDouble<end){Tick(0,p+Vector3.up*.22f+Vector3.forward*.10f,0);Record(ao);yield return null;}hands.ReleaseAll(false);float pinnedY=ao.Front.Positions[index].y;yield return new WaitForSecondsRealtime(1);result.pinHold=Mathf.Abs(ao.Front.Positions[index].y-pinnedY)<.06f;Check(result.pinHold,"Virtual arrangement pin did not hold");ao.ToggleArrangement();ao.Wake();yield return new WaitForSecondsRealtime(2.5f);result.pinDropM=pinnedY-ao.Front.Positions[index].y;result.pinRelease=result.pinDropM>.05f;Check(result.pinRelease,"Released pin did not restore gravity");Export(ao,"Player_Unpinned");ao.SetDesign(.90f,1.10f);yield return new WaitForSecondsRealtime(1.5f);result.design=Mathf.Abs(ao.LengthScale-.90f)<.001f&&Mathf.Abs(ao.WidthScale-1.10f)<.001f;Check(result.design,"Design edit did not persist");Export(ao,"Player_Design");hands.Hide();Capture("AoDaiPlayer.png");app.PoseStudio.Wear(0,5);yield return new WaitForSecondsRealtime(.4f);Capture("RepairedPoseShoulders.png");Check(result.exceptions==0,"Unity errors in exported player");}
  void Grip(int side,Vector3 p,bool remove){Physics.SyncTransforms();if(app.Player.VRMenu)app.Player.VRMenu.Hide();hands.Step(side,true,p,Quaternion.identity,0,remove?1:0,Time.unscaledDeltaTime);hands.Step(side,true,p,Quaternion.identity,1,remove?1:0,Time.unscaledDeltaTime);}
  void Tick(int side,Vector3 p,float trigger){hands.Step(side,true,p,Quaternion.identity,1,trigger,Time.unscaledDeltaTime);}
  static Vector3 Chest(ElasticSurface s){var v=s.MeshAt(0).vertices;int best=0;float d=float.PositiveInfinity;for(int i=0;i<v.Length;i++){float e=(v[i]-new Vector3(-.1f,1.28f,.16f)).sqrMagnitude;if(e<d){d=e;best=i;}}return s.transform.TransformPoint(v[best]);}
  static float Error(Vector3[] a,Vector3[] b){float e=0;for(int i=0;i<a.Length;i++)e+=(a[i]-b[i]).sqrMagnitude;return Mathf.Sqrt(e/a.Length);}
  void Record(LayeredAoDai ao){times.Add(Time.unscaledDeltaTime*1000);result.maxLayerMs=Math.Max(result.maxLayerMs,ao.Milliseconds);}
  void Save(){if(times.Count>0){float sum=0;foreach(float f in times)sum+=f;times.Sort();result.meanFrameMs=sum/times.Count;result.p95FrameMs=times[Math.Min(times.Count-1,(int)(times.Count*.95f))];}File.WriteAllText(output+"/player.json",JsonUtility.ToJson(result,true));Debug.Log("LAYERED_PLAYER "+JsonUtility.ToJson(result));}
  void Export(LayeredAoDai ao,string name){var body=new Mesh();var avatar=ao.Avatar;var old=avatar.Renderer.sharedMesh;avatar.Renderer.sharedMesh=avatar.BodyMesh;avatar.Renderer.BakeMesh(body);avatar.Renderer.sharedMesh=old;using(var w=new BinaryWriter(File.Create(output+"/Contact/"+name+".bin"))){w.Write(0x4c415931);Write(w,body.vertices,body.triangles);Write(w,ao.Bodice.Surface.CurrentPoints,ao.Bodice.Surface.MeshAt(0).triangles);Write(w,ao.Pants.Surface.CurrentPoints,ao.Pants.Surface.MeshAt(0).triangles);Write(w,ao.Front.Positions,ao.Front.Faces);Write(w,ao.Back.Positions,ao.Back.Faces);}Destroy(body);}
  static void Write(BinaryWriter w,Vector3[] p,int[] t){w.Write(p.Length);foreach(var v in p){w.Write(v.x);w.Write(v.y);w.Write(v.z);}w.Write(t.Length);foreach(int i in t)w.Write(i);}
  void Capture(string name){var c=app.Player.View;c.rect=new Rect(0,0,1,1);c.transform.position=new Vector3(2.2f,1.55f,.9f);c.transform.LookAt(new Vector3(2.2f,1,-1.9f));var rt=new RenderTexture(1400,1100,24);var tex=new Texture2D(1400,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1100),0,0);tex.Apply();File.WriteAllBytes(output+"/"+name,tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;Destroy(tex);Destroy(rt);}}
  void OnDestroy(){Application.logMessageReceived-=Log;}
 }
}
